def makeFancyString(s: str) -> str:
    # Result list to build the fancy string
    res = []
    for c in s:
        # If we already have at least two characters, and both are equal to current, skip adding
        if len(res) >= 2 and res[-1] == c and res[-2] == c:
            continue
        res.append(c)
    return ''.join(res)
